class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        rewardValues.sort()
        maxs = 2 * rewardValues[-1]
        dp = [False] * (maxs + 1)
        dp[0] = True
        best = 0
        for v in rewardValues:
            for s in range(min(best, v - 1), -1, -1):
                if dp[s]:
                    dp[s + v] = True
                    best = max(best, s + v)
        return best

