class Solution {
public:
    int maxTotalReward(vector<int>& rewardValues) {
        sort(rewardValues.begin(), rewardValues.end());
        int mx = 2 * rewardValues.back();
        vector<char> dp(mx + 1, 0);
        dp[0] = 1;
        int best = 0;
        for (int v : rewardValues) {
            for (int s = min(best, v - 1); s >= 0; --s)
                if (dp[s]) { dp[s + v] = 1; best = max(best, s + v); }
        }
        return best;
    }
};

