class Solution {
    public int maxTotalReward(int[] rewardValues) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int v : rewardValues) set.add(v);
        java.math.BigInteger mask = java.math.BigInteger.ONE;
        for (int v : set) {
            java.math.BigInteger lowMask = java.math.BigInteger.ONE.shiftLeft(v).subtract(java.math.BigInteger.ONE);
            mask = mask.or(mask.and(lowMask).shiftLeft(v));
        }
        return mask.bitLength() - 1;
    }
}

