    const vals = [...new Set(rewardValues)].sort((a, b) => a - b);
    let mask = 1n;
    for (const v of vals) {
        const lowMask = (1n << BigInt(v)) - 1n;
        mask |= (mask & lowMask) << BigInt(v);
    }
    return mask.toString(2).length - 1;
